import {
  useRef,
  useState,
  type CSSProperties,
  type HTMLAttributes,
  type PointerEvent as ReactPointerEvent,
} from "react";
import { mergeClasses } from "./classes";
import { fieldHintClasses, roundedClasses, type Rounded } from "./form";
import {
  BalsaThemeContext,
  useControllableState,
  useResolvedThemeProps,
} from "./theme-context";
import type { ThemeInput } from "./theme";

export type SliderModelValue = number | [number, number];
export type SliderOrientation = "horizontal" | "vertical";
export type SliderSize = "sm" | "md" | "lg";

export interface SliderProps extends Omit<HTMLAttributes<HTMLDivElement>, "onChange" | "value" | "defaultValue"> {
  id: string;
  label: string;
  min?: number;
  max?: number;
  step?: number;
  minStepsBetweenThumbs?: number;
  orientation?: SliderOrientation;
  size?: SliderSize;
  rounded?: Rounded;
  disabled?: boolean;
  required?: boolean;
  showLabel?: boolean;
  showValue?: boolean;
  name?: string;
  hint?: string;
  formatValue?: (value: number) => string;
  theme?: ThemeInput;
  value?: SliderModelValue;
  defaultValue?: SliderModelValue;
  onValueChange?: (value: SliderModelValue) => void;
}

export function Slider(rawProps: SliderProps) {
  const { props, theme } = useResolvedThemeProps("slider", "fields", rawProps, {
    size: "md",
    rounded: "full",
  } as const);
  const {
    id,
    label,
    min = 0,
    max = 100,
    step = 1,
    minStepsBetweenThumbs = 0,
    orientation = "horizontal",
    size,
    rounded,
    disabled = false,
    required = false,
    showLabel = true,
    showValue = true,
    name,
    hint,
    formatValue,
    theme: _themeInput,
    value,
    defaultValue = 0,
    onValueChange,
    className,
    style,
    ...domProps
  } = props;
  void _themeInput;

  const [current, setValue] = useControllableState<SliderModelValue>({
    value,
    defaultValue,
    onChange: onValueChange,
  });
  const controlElement = useRef<HTMLDivElement | null>(null);
  const [draggingPointerId, setDraggingPointerId] = useState<number | null>(null);

  const isRange = Array.isArray(current);
  const safeMin = Math.min(min, max);
  const safeMax = Math.max(min, max);
  const safeStep = step > 0 ? step : 1;
  const minimumGap = Math.max(0, minStepsBetweenThumbs) * safeStep;

  function clamp(next: number): number {
    return Math.min(safeMax, Math.max(safeMin, next));
  }

  const values: [number, number] = (() => {
    if (Array.isArray(current)) {
      const lower = clamp(Math.min(current[0] ?? safeMin, current[1] ?? safeMax));
      const upper = clamp(Math.max(current[0] ?? safeMin, current[1] ?? safeMax));
      return [lower, upper];
    }
    return [safeMin, clamp(current)];
  })();

  function percentage(next: number): number {
    const span = safeMax - safeMin;
    return span === 0 ? 0 : ((next - safeMin) / span) * 100;
  }

  const percentages: [number, number] = [percentage(values[0]), percentage(values[1])];
  const hintId = hint ? `${id}-hint` : undefined;
  const start = isRange ? percentages[0] : 0;
  const end = percentages[1];
  const fillStyle = orientation === "vertical"
    ? { bottom: `${start}%`, height: `${Math.max(0, end - start)}%` }
    : { left: `${start}%`, width: `${Math.max(0, end - start)}%` };

  function thumbStyle(position: number): CSSProperties {
    return orientation === "vertical"
      ? { bottom: `${position}%`, left: "50%", transform: "translate(-50%, 50%)" }
      : { left: `${position}%`, top: "50%", transform: "translate(-50%, -50%)" };
  }

  function format(next: number): string {
    return formatValue ? formatValue(next) : String(next);
  }

  function updateModel(index: 0 | 1, nextValue: number): void {
    const next = clamp(nextValue);
    if (!isRange) {
      setValue(next);
      return;
    }
    const [lower, upper] = values;
    setValue(
      index === 0
        ? [Math.min(next, upper - minimumGap), upper]
        : [lower, Math.max(next, lower + minimumGap)],
    );
  }

  function valueFromPointer(event: ReactPointerEvent<HTMLElement>): number | undefined {
    const bounds = controlElement.current?.getBoundingClientRect();
    if (!bounds || bounds.width === 0 || bounds.height === 0) return undefined;
    const position = orientation === "vertical"
      ? (bounds.bottom - event.clientY) / bounds.height
      : (event.clientX - bounds.left) / bounds.width;
    const raw = safeMin + Math.max(0, Math.min(1, position)) * (safeMax - safeMin);
    return safeMin + Math.round((raw - safeMin) / safeStep) * safeStep;
  }

  function updateFromPointer(index: 0 | 1, event: ReactPointerEvent<HTMLElement>): void {
    const next = valueFromPointer(event);
    if (next !== undefined) updateModel(index, next);
  }

  function handleThumbPointerDown(index: 0 | 1, event: ReactPointerEvent<HTMLElement>): void {
    if (disabled) return;
    event.preventDefault();
    setDraggingPointerId(event.pointerId);
    event.currentTarget.setPointerCapture?.(event.pointerId);
    controlElement.current
      ?.querySelectorAll<HTMLInputElement>('[data-balsa="slider-native"]')
      .item(index)
      ?.focus();
    updateFromPointer(index, event);
  }

  function handleThumbPointerMove(index: 0 | 1, event: ReactPointerEvent<HTMLElement>): void {
    if (draggingPointerId === event.pointerId) updateFromPointer(index, event);
  }

  function handleThumbPointerEnd(event: ReactPointerEvent<HTMLElement>): void {
    if (draggingPointerId === event.pointerId) setDraggingPointerId(null);
  }

  const trackSize = size === "sm"
    ? orientation === "vertical" ? "w-1" : "h-1"
    : size === "lg"
      ? orientation === "vertical" ? "w-2" : "h-2"
      : orientation === "vertical" ? "w-1.5" : "h-1.5";
  const thumbSize = size === "sm" ? "size-4" : size === "lg" ? "size-6" : "size-5";
  const thumbClasses = mergeClasses(
    "absolute z-30 rounded-full border-2 border-balsa-primary bg-balsa-input shadow-balsa-detail transition-[box-shadow,opacity] group-focus-within:ring-2 group-focus-within:ring-balsa-focus-ring/30",
    disabled ? "pointer-events-none bg-balsa-disabled opacity-60" : "cursor-grab touch-none active:cursor-grabbing",
    thumbSize,
  );
  const nativeClasses = mergeClasses(
    "absolute inset-0 z-20 m-0 size-full appearance-none bg-transparent opacity-0 outline-none",
    orientation === "vertical" ? "[writing-mode:vertical-lr] [direction:rtl]" : "",
    disabled ? "cursor-not-allowed" : "cursor-pointer",
  );
  const displayValue = isRange
    ? `${format(values[0])} – ${format(values[1])}`
    : format(values[1]);
  const firstThumbIndex: 0 | 1 = isRange ? 0 : 1;

  return (
    <BalsaThemeContext.Provider value={theme}>
      <div
        {...domProps}
        data-balsa="slider"
        data-theme={theme.explicitPresentation?.id}
        data-theme-base={theme.explicitPresentation?.base}
        data-orientation={orientation}
        data-size={size}
        data-rounded={rounded}
        className={mergeClasses(
          orientation === "vertical" ? "inline-flex min-h-64 flex-col" : "w-full",
          className,
        )}
        style={
          {
            ...theme.explicitPresentation?.style,
            ...style,
          } as CSSProperties
        }
      >
        {showValue ? (
          <div
            className={mergeClasses(
              "mb-balsa-xs flex items-center gap-balsa-lg",
              showLabel ? "justify-between" : "justify-end",
            )}
          >
            <label
              id={`${id}-label`}
              htmlFor={`${id}-0`}
              className={showLabel ? "text-sm font-medium text-balsa-foreground" : "sr-only"}
            >
              {label}
              {required ? <span className="text-balsa-primary" aria-hidden="true">*</span> : null}
            </label>
            <output className="text-sm tabular-nums text-balsa-muted-foreground">
              {displayValue}
            </output>
          </div>
        ) : (
          <label
            id={`${id}-label`}
            htmlFor={`${id}-0`}
            className={showLabel
              ? "mb-balsa-xs block text-sm font-medium text-balsa-foreground"
              : "sr-only"}
          >
            {label}
            {required ? <span className="text-balsa-primary" aria-hidden="true">*</span> : null}
          </label>
        )}

        <div
          ref={controlElement}
          className={mergeClasses(
            "group relative isolate focus-within:outline-none",
            orientation === "vertical" ? "min-h-48 w-10 flex-1 self-center" : "h-10 w-full",
          )}
        >
          <span
            aria-hidden="true"
            className={mergeClasses(
              "absolute bg-balsa-muted",
              roundedClasses[rounded],
              orientation === "vertical"
                ? "bottom-0 left-1/2 top-0 -translate-x-1/2"
                : "left-0 right-0 top-1/2 -translate-y-1/2",
              trackSize,
            )}
          />
          <span
            aria-hidden="true"
            className={mergeClasses(
              "absolute bg-balsa-primary",
              roundedClasses[rounded],
              orientation === "vertical"
                ? "bottom-0 left-1/2 -translate-x-1/2"
                : "top-1/2 -translate-y-1/2",
              trackSize,
            )}
            style={fillStyle}
          />
          <span
            data-balsa="slider-thumb"
            data-index={firstThumbIndex}
            className={thumbClasses}
            style={thumbStyle(isRange ? percentages[0] : percentages[1])}
            aria-hidden="true"
            onPointerDown={(event) => handleThumbPointerDown(firstThumbIndex, event)}
            onPointerMove={(event) => handleThumbPointerMove(firstThumbIndex, event)}
            onPointerUp={handleThumbPointerEnd}
            onPointerCancel={handleThumbPointerEnd}
          />
          {isRange ? (
            <span
              data-balsa="slider-thumb"
              data-index={1}
              className={thumbClasses}
              style={thumbStyle(percentages[1])}
              aria-hidden="true"
              onPointerDown={(event) => handleThumbPointerDown(1, event)}
              onPointerMove={(event) => handleThumbPointerMove(1, event)}
              onPointerUp={handleThumbPointerEnd}
              onPointerCancel={handleThumbPointerEnd}
            />
          ) : null}

          <input
            id={`${id}-0`}
            data-balsa="slider-native"
            type="range"
            min={safeMin}
            max={isRange ? values[1] - minimumGap : safeMax}
            step={safeStep}
            value={isRange ? values[0] : values[1]}
            name={isRange && name ? `${name}[]` : name}
            disabled={disabled}
            required={required}
            aria-labelledby={isRange ? undefined : `${id}-label`}
            aria-describedby={hintId}
            aria-label={isRange ? `${label} minimum` : undefined}
            aria-valuetext={format(isRange ? values[0] : values[1])}
            className={nativeClasses}
            onChange={(event) => updateModel(isRange ? 0 : 1, event.currentTarget.valueAsNumber)}
          />
          {isRange ? (
            <input
              id={`${id}-1`}
              data-balsa="slider-native"
              type="range"
              min={values[0] + minimumGap}
              max={safeMax}
              step={safeStep}
              value={values[1]}
              name={name ? `${name}[]` : undefined}
              disabled={disabled}
              required={required}
              aria-describedby={hintId}
              aria-label={`${label} maximum`}
              aria-valuetext={format(values[1])}
              className={nativeClasses}
              onChange={(event) => updateModel(1, event.currentTarget.valueAsNumber)}
            />
          ) : null}
        </div>

        {hint ? (
          <span id={hintId} className={fieldHintClasses}>{hint}</span>
        ) : null}
      </div>
    </BalsaThemeContext.Provider>
  );
}

import { extendTailwindMerge, type ClassNameValue } from "tailwind-merge";

/**
 * Every custom scale has to be declared here, not only defined in CSS.
 *
 * tailwind-merge decides which of two classes wins by knowing they belong to
 * the same group. A scale it has not been told about is not a group, so a
 * component's own `gap-balsa-md` and a caller's `gap-3` both survive the merge
 * and whichever CSS rule happens to come last decides — the caller's override
 * silently stops working. That is what happened the moment the spacing scale
 * landed, and it is invisible in the source: the class list looks right.
 */
const twMerge = extendTailwindMerge({
  extend: {
    theme: {
      radius: ["balsa-control", "balsa-surface", "balsa-panel"],
      text: [
        "balsa-2xs",
        "balsa-xs",
        "balsa-sm",
        "balsa-base",
        "balsa-prose",
        "balsa-lg",
        "balsa-xl",
        "balsa-2xl",
        "balsa-3xl",
        "balsa-4xl",
        "balsa-5xl",
        "balsa-6xl",
      ],
      leading: ["balsa-tight", "balsa-snug", "balsa-normal", "balsa-relaxed", "balsa-prose"],
      tracking: ["balsa-title", "balsa-normal", "balsa-label"],
      shadow: [
        "balsa-control",
        "balsa-surface",
        "balsa-panel",
        "balsa-sm",
        "balsa-md",
        "balsa-lg",
        "balsa-detail",
      ],
      spacing: [
        "balsa-4xs",
        "balsa-3xs",
        "balsa-2xs",
        "balsa-xs",
        "balsa-sm",
        "balsa-md",
        "balsa-lg",
        "balsa-xl",
        "balsa-2xl",
        "balsa-3xl",
        "balsa-section-sm",
        "balsa-section-md",
        "balsa-section-lg",
        "balsa-control-inline",
        "balsa-density-compact",
        "balsa-density-default",
        "balsa-density-comfortable",
      ],
    },
    classGroups: {
      // `backdrop-balsa` is a custom utility rather than a value on a scale, so
      // it has to join the group it competes with by name. Without this a
      // caller's `backdrop-blur-none` and the component's `backdrop-balsa` both
      // survive the merge and CSS order decides which blur wins — the same
      // failure the spacing scale hit the moment it landed.
      "backdrop-blur": ["backdrop-balsa", "backdrop-balsa-overlay"],
    },
  },
});

export function mergeClasses(...inputs: unknown[]): string {
  return twMerge(...(inputs as ClassNameValue[]));
}

export function withoutClassAttribute(
  attrs: Readonly<Record<string, unknown>>,
): Record<string, unknown> {
  return Object.fromEntries(
    Object.entries(attrs).filter(([name]) => name !== "class"),
  );
}

import { CircleAlert, CircleCheckBig } from "lucide-react";
import type { IconComponent } from "./Icon";

export const fieldLabelClasses =
  "mb-balsa-2xs block text-sm font-medium leading-snug text-balsa-foreground";

export const fieldHintClasses = "mt-balsa-2xs block text-sm text-balsa-muted-foreground";

export const textControlClasses =
  "w-full rounded-lg border font-balsa-body text-balsa-input-foreground outline-none transition-[border-color,box-shadow,opacity] placeholder:text-balsa-muted-foreground focus:border-balsa-focus-ring focus:ring-2 focus:ring-balsa-focus-ring/30 disabled:border-balsa-border disabled:bg-balsa-disabled disabled:text-balsa-disabled-foreground";

export const textControlPopupClasses =
  "max-h-64 overflow-auto rounded-lg p-balsa-3xs text-balsa-surface-elevated-foreground shadow-balsa-surface transition-[opacity,transform,visibility] duration-balsa-fast ease-balsa";

export const textControlOptionClasses =
  "flex min-h-8 w-full items-center justify-between rounded-md px-balsa-sm py-balsa-2xs text-left text-sm transition-colors";

/*
 * No bare `border`. Tailwind compiles it to a literal 1px, which outranks the
 * `border-width: var(--balsa-border-width)` the stylesheet sets on these
 * controls -- so a checkbox and a radio kept a 1px edge at every border
 * setting while everything around them moved. The colour utilities stay; only
 * the width comes from the token.
 */
export const choiceInputClasses =
  "shrink-0 cursor-pointer appearance-none outline-none transition-[border-color,background-color,box-shadow,opacity] focus-visible:border-balsa-focus-ring focus-visible:ring-2 focus-visible:ring-balsa-focus-ring/30 disabled:cursor-not-allowed disabled:border-balsa-border disabled:bg-balsa-disabled";

export type FieldStatus = "default" | "validated" | "unvalidated";
export type FieldSize = "sm" | "md";
export type FieldVariant = "outline" | "surface" | "soft" | "glass";
export type Rounded = "none" | "sm" | "md" | "lg" | "xl" | "2xl" | "3xl" | "full";
export type TextareaResize = "none" | "vertical" | "both";

export const roundedClasses: Readonly<Record<Rounded, string>> = {
  none: "rounded-none",
  sm: "rounded-sm",
  md: "rounded-md",
  lg: "rounded-lg",
  xl: "rounded-xl",
  "2xl": "rounded-2xl",
  "3xl": "rounded-3xl",
  full: "rounded-full",
};

/**
 * A surface that may be contained by another one.
 *
 * `auto` means "concentric with whatever contains me": the corner follows the
 * containing surface's radius minus the inset between them, so the gap between
 * the two edges stays even instead of thickening at every corner. A surface
 * standing on its own finds nothing published to nest inside and keeps the
 * ordinary surface radius.
 *
 * Kept apart from `Rounded` because that union is shared with text controls,
 * where there is nothing to be concentric with and `auto` would be a value
 * nobody could act on.
 */
export type SurfaceRounded = Rounded | "auto";

export const surfaceRoundedClasses: Readonly<Record<SurfaceRounded, string>> = {
  ...roundedClasses,
  // Deliberately no class. The radius comes from the concentric rule in
  // balsa-theme.css, keyed on data-rounded="auto"; a utility emitted here would
  // outrank it and pin the corner to one value.
  auto: "",
};

const fieldVariantClasses: Readonly<Record<FieldVariant, string>> = {
  outline: "border-balsa-input-border bg-balsa-background",
  surface: "border-balsa-input-border bg-balsa-input",
  soft: "border-transparent bg-balsa-muted",
  glass: "border-balsa-border/70 bg-balsa-surface/70 backdrop-balsa",
};

const fieldPopupVariantClasses: Readonly<Record<FieldVariant, string>> = {
  outline: "border-balsa-input-border bg-balsa-background",
  surface: "border-balsa-border-strong bg-balsa-surface-elevated",
  soft: "border-transparent bg-balsa-muted",
  glass: "border-balsa-border/70 bg-balsa-surface/80 backdrop-balsa",
};

export interface AnchoredPopupPosition {
  left: number;
  top: number;
  width: number;
}

const textControlSizeClasses: Record<FieldSize, string[]> = {
  sm: ["h-8", "px-balsa-md", "text-sm"],
  md: ["h-9", "px-balsa-md", "text-sm"],
};

const textareaResizeClasses: Readonly<Record<TextareaResize, string>> = {
  none: "resize-none",
  vertical: "resize-y",
  both: "resize",
};

export const fieldStatusMessages: Record<
  Extract<FieldStatus, "unvalidated">,
  string
> = {
  unvalidated: "Check this information and try again.",
};

export function getTextControlClasses(
  status: FieldStatus,
  hasAdornment: boolean,
  disabled: boolean,
  loading: boolean,
  size: FieldSize = "md",
  rounded: Rounded = "lg",
  variant: FieldVariant = "surface",
): string[] {
  const resolvedSize = textControlSizeClasses[size] ? size : "md";
  return [
    textControlClasses,
    fieldVariantClasses[variant],
    roundedClasses[rounded],
    ...textControlSizeClasses[resolvedSize],
    ...(loading
      ? ["disabled:cursor-progress"]
      : disabled
        ? ["disabled:cursor-not-allowed"]
        : ["cursor-pointer"]),
    ...(status === "validated" ? ["border-balsa-success", "focus:border-balsa-success"] : []),
    ...(status === "unvalidated"
      ? ["border-balsa-destructive", "focus:border-balsa-destructive", "focus:ring-balsa-destructive/30"]
      : []),
    ...(hasAdornment ? ["pr-10"] : []),
  ];
}

export function getTextControlPopupClasses(
  rounded: Rounded = "lg",
  variant: FieldVariant = "surface",
): string[] {
  return [textControlPopupClasses, roundedClasses[rounded], fieldPopupVariantClasses[variant]];
}

export function getTextareaControlClasses(
  status: FieldStatus,
  disabled: boolean,
  loading: boolean,
  size: FieldSize = "md",
  rounded: Rounded = "lg",
  resizable: TextareaResize = "vertical",
  hasAdornment = false,
  variant: FieldVariant = "surface",
): string[] {
  return [
    textControlClasses,
    fieldVariantClasses[variant],
    "h-auto min-h-0 py-balsa-xs leading-6",
    roundedClasses[rounded],
    textareaResizeClasses[resizable],
    size === "sm" ? "px-balsa-md text-sm leading-5" : "px-balsa-md text-sm leading-6",
    ...(loading
      ? ["disabled:cursor-progress"]
      : disabled
        ? ["disabled:cursor-not-allowed"]
        : ["cursor-text"]),
    ...(status === "validated" ? ["border-balsa-success", "focus:border-balsa-success"] : []),
    ...(status === "unvalidated"
      ? ["border-balsa-destructive", "focus:border-balsa-destructive", "focus:ring-balsa-destructive/30"]
      : []),
    ...(hasAdornment ? ["pr-10"] : []),
  ];
}

export function getChoiceInputClasses(variant: FieldVariant = "surface"): string[] {
  return [choiceInputClasses, fieldVariantClasses[variant]];
}

export function getChoiceTrackClasses(variant: FieldVariant = "surface"): string {
  return fieldVariantClasses[variant];
}

export function getAnchoredPopupPosition(
  trigger: HTMLElement,
  popup: HTMLElement,
  fallbackHeight = 256,
): AnchoredPopupPosition {
  const triggerRect = trigger.getBoundingClientRect();
  const popupRect = popup.getBoundingClientRect();
  const viewportPadding = 8;
  const gap = 8;
  const width = Math.min(
    triggerRect.width,
    window.innerWidth - viewportPadding * 2,
  );
  const height = popupRect.height || fallbackHeight;
  const maxLeft = Math.max(
    viewportPadding,
    window.innerWidth - width - viewportPadding,
  );

  return {
    width,
    left: Math.min(Math.max(triggerRect.left, viewportPadding), maxLeft),
    top:
      triggerRect.bottom + gap + height <= window.innerHeight - viewportPadding
        ? triggerRect.bottom + gap
        : Math.max(viewportPadding, triggerRect.top - height - gap),
  };
}

export function getFieldStatusIcon(status: FieldStatus): IconComponent | undefined {
  if (status === "validated") return CircleCheckBig;
  if (status === "unvalidated") return CircleAlert;
  return undefined;
}

export function getFieldStateColorClass(status: FieldStatus): string {
  if (status === "unvalidated") return "text-balsa-destructive";
  if (status === "validated") return "text-balsa-success";
  return "text-balsa-muted-foreground";
}
